package com.chahinaz.pos.operations;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="manager_approval") public class ManagerApproval {@Id public UUID id;@Column(name="operation_type",nullable=false,length=40)public String operationType;@Column(name="requesting_employee_id",nullable=false)public UUID requestingEmployeeId;@Column(name="approving_employee_id",nullable=false)public UUID approvingEmployeeId;@Column(name="target_type",nullable=false,length=40)public String targetType;@Column(name="target_id",nullable=false)public UUID targetId;@Column(nullable=false,length=500)public String reason;@Column(name="approved_at",nullable=false)public Instant approvedAt;@Column(name="consumed_at")public Instant consumedAt;protected ManagerApproval(){}public ManagerApproval(String op,UUID request,UUID approver,String type,UUID target,String reason){id=UUID.randomUUID();operationType=op;requestingEmployeeId=request;approvingEmployeeId=approver;targetType=type;targetId=target;this.reason=reason;approvedAt=Instant.now();}}
